(function(){
  if (window.__cartInstalled__) return;
  window.__cartInstalled__ = true;
  var canvas = document.getElementById('cartCanvas');
  var ctx = canvas.getContext('2d');
  var m1Slider = document.getElementById('m1Slider');
  var m1Val = document.getElementById('m1Val');
  var m2Slider = document.getElementById('m2Slider');
  var m2Val = document.getElementById('m2Val');
  var out = document.getElementById('cartOut');
  var playBtn = document.getElementById('playBtn');
  var running = false, t = 0;
  var K = 1, pushT = 0.35, scale = 130;
  window.simState = { m1: 5, m2: 8, t: 0, running: false, push: true, v1: 0, v2: 0 };
  function compute(){
    var m1 = parseFloat(m1Slider.value), m2 = parseFloat(m2Slider.value);
    window.simState.m1 = m1; window.simState.m2 = m2;
    return { m1: m1, m2: m2, v1: K / m1, v2: K / m2 };
  }
  function cart(x, y, w, h, color, label){
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y); ctx.lineTo(x + w, y); ctx.lineTo(x + w, y + h);
    ctx.lineTo(x, y + h); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 1.5;
    ctx.strokeRect(x, y, w, h);
    for (var wx = 0; wx < 2; wx++) {
      var cx = x + w * (0.28 + wx * 0.44), cy = y + h + 6, r = 5;
      ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fillStyle = '#334155'; ctx.fill(); ctx.stroke();
    }
    ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(label, x + w / 2, y + h / 2);
  }
  function arrow(x1, y1, x2, y2, color){
    var dx = x2 - x1, dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len < 3) return;
    var ux = dx / len, uy = dy / len;
    ctx.strokeStyle = color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2 - ux * 2, y2 - uy * 2); ctx.stroke();
    var ah = 8;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - ux * ah - uy * ah * 0.5, y2 - uy * ah + ux * ah * 0.5);
    ctx.lineTo(x2 - ux * ah + uy * ah * 0.5, y2 - uy * ah - ux * ah * 0.5);
    ctx.closePath(); ctx.fill();
  }
  function draw(){
    var p = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var GY = 300;
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, GY); ctx.lineTo(canvas.width, GY); ctx.stroke();
    var cw = 70, ch = 44;
    var cy = GY - ch;
    var gap = 0;
    var x1, x2;
    if (running) {
      if (t > pushT) {
        var dt = t - pushT;
        x1 = (canvas.width / 2 - cw) + p.v1 * scale * dt;
        x2 = (canvas.width / 2) - p.v2 * scale * dt;
        window.simState.push = false;
      } else {
        gap = 2 + t / pushT * 14;
        x1 = canvas.width / 2 - cw - gap;
        x2 = canvas.width / 2 + gap;
        window.simState.push = true;
      }
    } else {
      gap = 4;
      x1 = canvas.width / 2 - cw - gap;
      x2 = canvas.width / 2 + gap;
      window.simState.push = true;
    }
    cart(x1, cy, cw, ch, '#dc2626', 'm₁');
    cart(x2, cy, cw, ch, '#2563eb', 'm₂');
    var midX = (x1 + cw + x2) / 2;
    if (running && t <= pushT) {
      ctx.strokeStyle = '#f59e0b'; ctx.lineWidth = 2.5;
      ctx.beginPath();
      for (var i = 0; i <= 6; i++) {
        var sx = midX - 12 + i * 4;
        var sy = cy + ch / 2 + (i % 2 === 0 ? -10 : 10);
        if (i === 0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
      }
      ctx.stroke();
      arrow(x1 + cw, cy + ch / 2, x1 + cw + 56, cy + ch / 2, '#dc2626');
      arrow(x2, cy + ch / 2, x2 - 56, cy + ch / 2, '#2563eb');
      ctx.fillStyle = '#334155'; ctx.font = 'bold 13px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('F₁₂', x1 + cw + 32, cy + ch / 2 - 14);
      ctx.fillText('F₂₁', x2 - 32, cy + ch / 2 - 14);
    }
    if (running && t > pushT) {
      ctx.fillStyle = '#334155'; ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('v₁ = ' + p.v1.toFixed(2) + ' m/s', x1 + cw / 2, cy - 14);
      ctx.fillText('v₂ = ' + p.v2.toFixed(2) + ' m/s', x2 + cw / 2, cy - 14);
    }
    m1Val.textContent = p.m1;
    m2Val.textContent = p.m2;
    var p1 = p.m1 * p.v1, p2 = p.m2 * p.v2;
    out.textContent = running
      ? (t <= pushT
          ? 'أثناء الدفع: F₁₂ = F₂₁ (متساويتان في المقدار، متعاكستان في الاتجاه)'
          : 'بعد التفاعل: v₁/v₂ = m₂/m₁ | كمية الحركة m₁v₁ = ' + p1.toFixed(1) + ' = m₂v₂ = ' + p2.toFixed(1))
      : 'اضغط تشغيل لبدء التفاعل (القوتان متساويتان في المقدار ومتعاكستان في الاتجاه)';
    window.simState.v1 = p.v1; window.simState.v2 = p.v2; window.simState.t = t;
  }
  playBtn.addEventListener('click', function(){
    if (!running) { t = 0; }
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل التفاعل';
  });
  m1Slider.addEventListener('input', function(){});
  m2Slider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){
    if (running) {
      t += 0.016;
      if (t > pushT + 6) t = 0;
    }
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
